def C(*keys):
    parts = []
    for k in keys:
        f_, e_, y_ = G.CITE[k]; mk = "" if e_ in d.seen else f"[[fn:{e_}]]"; d.seen.add(e_); parts.append(f"{f_}{mk}، {y_}")
    return "(" + "؛ ".join(parts) + ")"
def Cn(k):
    f_, e_, y_ = G.CITE[k]; mk = "" if e_ in d.seen else f"[[fn:{e_}]]"; d.seen.add(e_); return f"{f_}{mk} ({y_})"
